'use strict';

import { createError, IDB_ERROR } from 'pouchdb-errors';
import { collectConflicts } from 'pouchdb-merge';

import { DOC_STORE, processAttachment } from './util';

const FINAL_STRING = String.fromCharCode(0xFFFF); // probably the last string, except for String.fromCharCode(0xFFFF) + String.fromCharCode(0xFFFF) etc.

function allDocsKeys(keys, docStore, allDocsInner) {
  // It's not guaranted to be returned in right order
  const valuesBatch = new Array(keys.length);
  let count = 0;
  keys.forEach(function (key, index) {
    docStore.get(key).onsuccess = function (event) {
      valuesBatch[index] = event.target.result || {key, error: 'not_found'};
      if (++count === keys.length) valuesBatch.forEach(allDocsInner);
    };
  });
}

function createKeyRange(start, end, inclusiveEnd, key, descending) {
  console.log('createKeyRange()', { start, end, inclusiveEnd, key, descending });
  try {
    if (key) {
      return IDBKeyRange.only([0, key]);
    } else if (descending) {
      return IDBKeyRange.bound(end, start, !inclusiveEnd, false);
    } else {
      return IDBKeyRange.bound(start, end, false, !inclusiveEnd);
    }
  } catch (e) {
    return {error: e};
  }
}

function handleKeyRangeError(opts, metadata, err, callback) {
  if (err.name === "DataError" && err.code === 0) {
    // data error, start is less than end
    var returnVal = {
      total_rows: metadata.doc_count,
      offset: opts.skip,
      rows: []
    };
    /* istanbul ignore if */
    if (opts.update_seq) {
      returnVal.update_seq = metadata.seq;
    }
    return callback(null, returnVal);
  }
  callback(createError(IDB_ERROR, err.name, err.message));
}

export default function (txn, metadata, opts, callback) {
  console.log('allDocs()', JSON.stringify(opts), callback.toString());
  if (txn.error) {
    return callback(txn.error);
  }

  // TODO: Weird hack, I dont like it
  if (opts.limit === 0) {
    var returnVal = {
      total_rows: metadata.doc_count,
      offset: opts.skip,
      rows: []
    };

    /* istanbul ignore if */
    if (opts.update_seq) {
      returnVal.update_seq = metadata.seq;
    }
    txn.txn.commit();
    return callback(null, returnVal);
  }

  var results = [];
  var processing = [];

  var key = 'key' in opts ? opts.key : false; // TODO how does this interact with skip & limit?  Surely a specific key with skip > 0 => no result?
  var keys = 'keys' in opts ? opts.keys : false;
  var skip = opts.skip || 0;
  var limit = typeof opts.limit === 'number' ? opts.limit : undefined;
  var inclusiveEnd = opts.inclusive_end !== false;
  var descending = 'descending' in opts && opts.descending ? 'prev' : null;
  var start = 'startkey' in opts ? opts.startkey : (descending ? FINAL_STRING : '');
  var end   = 'endkey'   in opts ? opts.endkey   : (descending ? '' : FINAL_STRING);

  var docStore = txn.txn.objectStore(DOC_STORE);

  if (keys) {
    txn.txn.oncomplete = onTxnComplete;
    const allDocsInner_keys = doc => {
      if (doc.error) {
        return results.push(doc);
      }

      const row = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };

      if (doc.deleted) {
        row.value.deleted = true;
        row.doc = null;
      } else if (opts.include_docs) {
        include_doc(processing, opts, row, doc);
      }

      results.push(row);
    };
    return allDocsKeys(keys, docStore, allDocsInner_keys);
  }

  let keyRange = createKeyRange([0, start], [0, end], inclusiveEnd, key, descending);
  if (keyRange.error) {
    return handleKeyRangeError(opts, metadata, keyRange.error, callback);
  }
  if(descending) {
    console.log('allDocs()', 'Initial key range:', keyRange.upper+`${isOpen(keyRange.upperOpen)}`, '->', keyRange.lower+`${isOpen(keyRange.lowerOpen)}`);
  } else {
    console.log('allDocs()', 'Initial key range:', keyRange.lower+`${isOpen(keyRange.lowerOpen)}`, '->', keyRange.upper+`${isOpen(keyRange.upperOpen)}`);
  }

  // XXX must be set AFTER key-range-error is generated
  txn.txn.oncomplete = onTxnComplete;

  function onTxnComplete() {
    const returnVal = {
      total_rows: metadata.doc_count,
      offset: 0,
      rows: results
    };
    /* istanbul ignore if */
    if (opts.update_seq) {
      returnVal.update_seq = metadata.seq;
    }

    if(processing.length) {
      Promise.all(processing).then(function () {
        callback(null, returnVal);
      });
    } else {
      callback(null, returnVal);
    }
  }

  const notDeletedDocsIndex = docStore.index('___not_deleted');

  if(skip) {
    notDeletedDocsIndex.openKeyCursor(keyRange, descending || 'next').onsuccess = (e) => {
      const cursor = e.target.result;
      if(!cursor) {
        return txn.txn.commit();
      }

      if(skip) {
        cursor.advance(skip);
        skip = 0;
        return;
      }

      const lastSkipped = cursor.key;
      if(lastSkipped === undefined) {
        // no results
        return txn.txn.commit();
      }

      if(descending) {
        keyRange = createKeyRange(lastSkipped, keyRange.lower /* both are already compound keys */, inclusiveEnd, key, descending);
      } else {
        keyRange = createKeyRange(lastSkipped, keyRange.upper /* both are already compound keys */, inclusiveEnd, key, descending);
      }
      if (keyRange.error) { // XXX this code should never be run, so can prob be removed
        txn.txn.abort();
        return handleKeyRangeError(opts, metadata, keyRange.error, callback);
      }
      if(descending) {
        console.log('allDocs()', 'Post-skip key range:', keyRange.upper+`${isOpen(keyRange.upperOpen)}`, '->', keyRange.lower+`${isOpen(keyRange.lowerOpen)}`);
      } else {
        console.log('allDocs()', 'Post-skip key range:', keyRange.lower+`${isOpen(keyRange.lowerOpen)}`, '->', keyRange.upper+`${isOpen(keyRange.upperOpen)}`);
      }

      fetchResults();
    };
  } else {
    fetchResults();
  }

  function fetchResults() {
    // TODO there is a risk here with getting all results into memory - if they
    // have multiple revs, then we risk loading loads of extra stuff which we
    // could be discarding with each batch.
    // TODO this also loads a lot of unused data when include_docs:false
    // Fastest and most pragmatic approach here is probably batching... except
    // that won't work descending.
    if(descending && limit) {
      // TODO getAll() does not support descending.  This will either need to be
      // achieved with a cursor, or by calling getAll(), iterating from the top,
      // and discarding.
      // TODO needs thought and optimisation
      notDeletedDocsIndex.getAll(keyRange).onsuccess = (e) => {
        const values = e.target.result;
        for(let i=values.length-1; i>=0 && limit--; --i) {
          const doc = values[i];
          const row = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };
          if(opts.include_docs) include_doc(processing, opts, row, doc);
          results[values.length - i - 1] = row;
        }
        return txn.txn.commit();
      };
    } else {
      notDeletedDocsIndex.getAll(keyRange, limit).onsuccess = (e) => {
        const values = e.target.result;
        for(let i=0; i<values.length; ++i) {
          const doc = values[descending?values.length-i-1:i];
          const row = { id:doc.id, key:doc.id, value:{ rev:doc.rev } };
          if(opts.include_docs) include_doc(processing, opts, row, doc);
          results[i] = row;
        }
        return txn.txn.commit();
      };
    }
  }
}

function include_doc(processing, opts, row, doc) {
  var docData = doc.revs[doc.rev].data;

  row.doc = docData;
  row.doc._id = doc.id;
  row.doc._rev = doc.rev;
  if (opts.conflicts) {
    var conflicts = collectConflicts(doc);
    if (conflicts.length) {
      row.doc._conflicts = conflicts;
    }
  }
  if (opts.attachments && docData._attachments) {
    for (var name in docData._attachments) {
      processing.push(processAttachment(name, doc, row.doc, opts.binary));
    }
  }
}

function isOpen(o) {
  return o ? 'x' : 'i';
}
